import{_ as t,o as a,c as n,a8 as r}from"./chunks/framework.CNIpabDg.js";const u=JSON.parse('{"title":"Explanation","description":"Understand how Xila fits together, why its major boundaries exist, and what trade-offs they create.","frontmatter":{"layout":"doc","docType":"explanation","description":"Understand how Xila fits together, why its major boundaries exist, and what trade-offs they create."},"headers":[],"relativePath":"explanation/index.md","filePath":"explanation/index.md","lastUpdated":1793045410000}'),o={name:"explanation/index.md"};function i(s,e,h,l,d,c){return a(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[...e[0]||(e[0]=[r('<h1 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h1><p>Explanation is where Xila&#39;s architecture is made understandable: what the main parts are, how they relate, and why the system is shaped this way.</p><p>If you are new to Xila, start with the <a href="./architecture/">architecture overview</a>. It gives you the mental model that the more detailed subsystem, library, driver, runtime, and storage pages build on.</p><h2 id="start-with-the-system" tabindex="-1">Start with the system <a class="header-anchor" href="#start-with-the-system" aria-label="Permalink to &quot;Start with the system&quot;">​</a></h2><ul><li><a href="./architecture/">Architecture overview</a> explains how executables, Xila services, shared contracts, drivers, and target platforms fit together.</li><li><a href="./architecture/components.html">Component map</a> helps you locate a subsystem, library, driver, or executable by the role it plays in that system.</li><li><a href="./architecture/subsystems/">Subsystems</a> explains runtime-owned services such as graphics, networking, tasks, time, and users.</li><li><a href="./architecture/libraries/">Libraries</a> documents reusable contracts and implementations.</li></ul><h2 id="follow-the-question-you-have" tabindex="-1">Follow the question you have <a class="header-anchor" href="#follow-the-question-you-have" aria-label="Permalink to &quot;Follow the question you have&quot;">​</a></h2><p><strong>How can the same Xila code run on an MCU, a native host, and in a browser?</strong></p><p>Read <a href="./development-environments.html">development environments and targets</a> for the relationship between toolchains, validation targets, and platform ownership.</p><p><strong>How will application packages be built, published and installed?</strong></p><p>Read <a href="./package-management.html">package management architecture</a> for the separation of portable Rust tooling, the static community registry preview and planned on-device trust/installer integration.</p><p><strong>How does the browser version keep a persistent disk?</strong></p><p>Read <a href="./browser-storage.html">browser storage</a> for the relationship between OPFS, the in-memory disk image, autosave, and durability.</p><p><strong>What happens when Xila executes a WebAssembly guest?</strong></p><p>Read the <a href="./architecture/executables/wasm.html">WASM runtime</a> for Wasmi integration, WASI imports, and cooperative execution.</p><p><strong>How do guest graphics calls cross into the host runtime?</strong></p><p>Read <a href="./architecture/executables/bindings.html">graphics bindings</a> for the ownership and memory boundary between guest handles and host objects.</p><h2 id="when-your-question-changes" tabindex="-1">When your question changes <a class="header-anchor" href="#when-your-question-changes" aria-label="Permalink to &quot;When your question changes&quot;">​</a></h2><p>Explanation is intentionally not a task guide or an API catalogue. When you know <em>why</em> a part of Xila works the way it does and want to do something with it, continue with the <a href="/how-to/">how-to guides</a>. When you need an exact command, limit, symbol, or API contract, use the <a href="/reference/">reference section</a>.</p>',18)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
